 480→  function wireWidget(wid, cfg, API_BASE, SHOP) {
 481→    var inp = document.getElementById(wid + "-inp");
 482→    var btn = document.getElementById(wid + "-btn");
 483→    var res = document.getElementById(wid + "-res");
 484→    if (!inp || !btn || !res) return;
 485→
 486→    function normalizeZip(raw) {
 487→      var z = raw.trim().toUpperCase();
 488→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
 489→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
 490→      return z;
 491→    }
 492→
 493→    // Store the original button HTML so we can restore it exactly after loading
 494→    var btnOriginalHtml = btn.innerHTML;
 495→
 496→    function setBtnLoading(loading) {
 497→      btn.disabled = loading;
 498→      if (loading) {
 499→        btn.classList.add('zcc-btn--loading');
 500→        // Replace entire button content with a lone spinner — no text overlap
 501→        btn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
 502→      } else {
 503→        btn.classList.remove('zcc-btn--loading');
 504→        // Restore original icon + label markup
 505→        btn.innerHTML = btnOriginalHtml;
 506→        // Keep button text in sync with config (merchant may have customised it)
 507→        var labelEl = btn.querySelector('.zcc-btn-label');
 508→        if (labelEl) labelEl.textContent = cfg.buttonText;
 509→      }
 510→    }
 511→
 512→    function checkZip() {
 513→      var zip = normalizeZip(inp.value);
 514→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
 515→      if (!zip) { inp.focus(); return; }
 516→
 517→      setBtnLoading(true);
 518→      res.innerHTML = "";
 519→
 520→      fetch(
 521→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
 522→          "&zip=" + encodeURIComponent(zip)
 523→      )
 524→        .then(function (r) {
 525→          if (!r.ok) {
 526→            // Non-2xx: try to parse JSON error body, fall back to status text
 527→            return r.json().catch(function() {
 528→              return { error: 'Server error (' + r.status + ')' };
 529→            });
 530→          }
 531→          return r.json();
 532→        })
 533→        .then(function (data) {
 534→          setBtnLoading(false);
 535→
 536→          // If the API returned an error object (no allowed field), treat as a
 537→          // transient server error and show it in the result area rather than
 538→          // falling through with undefined message text.
 539→          if (data.error && data.allowed === undefined) {
 540→            console.error('[Pinzo] API returned error:', data.error, '| API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"');
 541→            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
 542→            try {
 543→              sessionStorage.removeItem('zcc:valid');
 544→              sessionStorage.removeItem('zcc:zip');
 545→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
 546→            } catch(e) {}
 547→            return;
 548→          }
 549→
 550→          // Store validation result for cart page
 551→          try {
 552→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
 553→            sessionStorage.setItem('zcc:zip', zip);
 554→            sessionStorage.setItem('zcc:shop', SHOP);
 555→            // Fire custom event for other scripts to listen to
 556→            window.dispatchEvent(new CustomEvent('zcc:validated', {
 557→              detail: { valid: data.allowed, zip: zip }
 558→            }));
 559→          } catch(e) { /* sessionStorage may be unavailable */ }
 560→
 561→          if (data.allowed) {
 562→            var html = '<div class="zcc-result ok">' +
 563→              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
 564→              '<div class="zcc-result-content">' +
 565→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
 566→            if (cfg.showEta && data.eta) {
 567→              html += '<div class="zcc-meta">' + ICONS.truck + '<span>Estimated delivery: <strong>' + esc(data.eta) + '</strong></span></div>';
 568→            }
 569→            if (cfg.showZone && data.zone) {
 570→              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
 571→            }
 572→            if (cfg.showDeliveryDays && data.daysOfWeek) {
 573→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
 574→              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
 575→            }
 576→            if (cfg.showCutoffTime && data.cutoffTime) {
 577→              var parts = data.cutoffTime.split(':');
 578→              var hr = parseInt(parts[0], 10);
 579→              var min = parts[1] || '00';
 580→              var ampm = hr >= 12 ? 'PM' : 'AM';
 581→              var hr12 = hr % 12 || 12;
 582→              html += '<div class="zcc-meta zcc-cutoff">' + ICONS.clock + '<span>Order by <strong>' + hr12 + ':' + min + ' ' + ampm + '</strong> for same-day</span></div>';
 583→            }
 584→            if (cfg.showCod !== false) {
 585→              if (data.codAvailable === true) {
 586→                html += '<div class="zcc-cod zcc-cod--available">' + ICONS.card + ' Cash on Delivery Available</div>';
 587→              } else if (data.codAvailable === false) {
 588→                html += '<div class="zcc-cod zcc-cod--unavailable">' + ICONS.card + ' COD Not Available</div>';
 589→              }
